package com.manacore.core.storage;

import java.util.HashMap;
import java.util.Map;

/**
 * Sparse positional chunk storage for mana values.
 * Only stores non-zero mana values to maintain sparsity.
 * Unset positions read as zero; non-positive results are removed so storage remains sparse.
 * Mana values are always non-negative and finite.
 */
public class ChunkManaMap {

    /**
     * Map from chunk keys to chunk data.
     * Chunk key is a long packing chunk X, Y, Z coordinates.
     */
    private final Map<Long, ChunkData> chunks;

    /**
     * Creates a new empty ChunkManaMap.
     */
    public ChunkManaMap() {
        this.chunks = new HashMap<>();
    }

    /**
     * Gets the mana value at the specified world coordinates.
     * Unset positions return 0.
     *
     * @param x the world X coordinate
     * @param y the world Y coordinate
     * @param z the world Z coordinate
     * @return the mana value at the position (0 if unset)
     */
    public double get(int x, int y, int z) {
        long chunkKey = ManaCoordinates.chunkKey(
                ManaCoordinates.getChunkCoord(x),
                ManaCoordinates.getChunkCoord(y),
                ManaCoordinates.getChunkCoord(z));

        ChunkData chunk = chunks.get(chunkKey);
        if (chunk == null) {
            return 0.0;
        }

        short intraChunkKey = ManaCoordinates.intraChunkKey(
                ManaCoordinates.getIntraChunkCoord(x),
                ManaCoordinates.getIntraChunkCoord(y),
                ManaCoordinates.getIntraChunkCoord(z));

        Double value = chunk.positions.get(intraChunkKey);
        return value != null ? value : 0.0;
    }

    /**
     * Sets the mana value at the specified world coordinates.
     * If the value is non-positive (<= 0), the position is removed from storage.
     * If the value is NaN or infinite, it is treated as invalid and the position is removed.
     *
     * @param x the world X coordinate
     * @param y the world Y coordinate
     * @param z the world Z coordinate
     * @param value the mana value to set
     */
    public void set(int x, int y, int z, double value) {
        // Validate and clamp the value
        if (!isValidManaValue(value)) {
            remove(x, y, z);
            return;
        }

        long chunkKey = ManaCoordinates.chunkKey(
                ManaCoordinates.getChunkCoord(x),
                ManaCoordinates.getChunkCoord(y),
                ManaCoordinates.getChunkCoord(z));

        short intraChunkKey = ManaCoordinates.intraChunkKey(
                ManaCoordinates.getIntraChunkCoord(x),
                ManaCoordinates.getIntraChunkCoord(y),
                ManaCoordinates.getIntraChunkCoord(z));

        if (value <= 0) {
            // Remove non-positive values to maintain sparsity
            remove(x, y, z);
            return;
        }

        ChunkData chunk = chunks.computeIfAbsent(chunkKey, k -> new ChunkData());
        chunk.positions.put(intraChunkKey, value);
    }

    /**
     * Adds mana to the specified world coordinates.
     * If the result is non-positive, the position is removed from storage.
     *
     * @param x the world X coordinate
     * @param y the world Y coordinate
     * @param z the world Z coordinate
     * @param delta the mana value to add
     */
    public void add(int x, int y, int z, double delta) {
        // Reject non-finite deltas but allow negative finite values
        if (!Double.isFinite(delta)) {
            return;
        }

        double current = get(x, y, z);
        double result = current + delta;

        // Handle overflow
        if (Double.isInfinite(result)) {
            result = Double.MAX_VALUE;
        }

        set(x, y, z, result);
    }

    /**
     * Removes the mana value at the specified world coordinates.
     * This is a no-op if the position was not set.
     *
     * @param x the world X coordinate
     * @param y the world Y coordinate
     * @param z the world Z coordinate
     */
    public void remove(int x, int y, int z) {
        long chunkKey = ManaCoordinates.chunkKey(
                ManaCoordinates.getChunkCoord(x),
                ManaCoordinates.getChunkCoord(y),
                ManaCoordinates.getChunkCoord(z));

        ChunkData chunk = chunks.get(chunkKey);
        if (chunk == null) {
            return;
        }

        short intraChunkKey = ManaCoordinates.intraChunkKey(
                ManaCoordinates.getIntraChunkCoord(x),
                ManaCoordinates.getIntraChunkCoord(y),
                ManaCoordinates.getIntraChunkCoord(z));

        chunk.positions.remove(intraChunkKey);

        // Clean up empty chunks
        if (chunk.positions.isEmpty()) {
            chunks.remove(chunkKey);
        }
    }

    /**
     * Checks if a mana value is valid (non-negative, finite, and not NaN).
     *
     * @param value the value to check
     * @return true if the value is valid
     */
    private static boolean isValidManaValue(double value) {
        return value > 0 && Double.isFinite(value);
    }

    /**
     * Gets the number of chunks with stored mana values.
     *
     * @return the number of non-empty chunks
     */
    public int getChunkCount() {
        return chunks.size();
    }

    /**
     * Gets the number of positions with stored mana values.
     *
     * @return the number of non-zero positions
     */
    public int getPositionCount() {
        int count = 0;
        for (ChunkData chunk : chunks.values()) {
            count += chunk.positions.size();
        }
        return count;
    }

    /**
     * Clears all mana values from storage.
     */
    public void clear() {
        chunks.clear();
    }

    /**
     * Checks if the storage is empty.
     *
     * @return true if there are no stored mana values
     */
    public boolean isEmpty() {
        return chunks.isEmpty();
    }

    /**
     * Internal class representing the mana data for a single chunk.
     */
    private static final class ChunkData {
        /**
         * Map from intra-chunk position keys to mana values.
         * Only stores non-zero values.
         */
        final Map<Short, Double> positions;

        ChunkData() {
            this.positions = new HashMap<>();
        }
    }
}

package com.manacore.core;

/**
 * Math utilities for mana calculations.
 * Ensures mana values are always valid (non-negative, finite).
 */
public final class ManaMath {

    private ManaMath() {
        // Utility class - no instantiation
    }

    /**
     * Clamps a mana value to be non-negative.
     * Negative values become zero.
     *
     * @param value the mana value to clamp
     * @return the clamped mana value (>= 0)
     */
    public static double clampNonNegative(double value) {
        return Math.max(0.0, value);
    }

    /**
     * Clamps a mana value to be non-negative.
     *
     * @param value the mana value to clamp
     * @return the clamped mana value (>= 0)
     */
    public static float clampNonNegative(float value) {
        return Math.max(0.0f, value);
    }

    /**
     * Clamps a mana value to be non-negative.
     *
     * @param value the mana value to clamp
     * @return the clamped mana value (>= 0)
     */
    public static int clampNonNegative(int value) {
        return Math.max(0, value);
    }

    /**
     * Clamps a mana value to be non-negative.
     *
     * @param value the mana value to clamp
     * @return the clamped mana value (>= 0)
     */
    public static long clampNonNegative(long value) {
        return Math.max(0L, value);
    }

    /**
     * Checks if a mana value is valid (non-negative and finite).
     *
     * @param value the mana value to check
     * @return true if the value is valid (>= 0 and finite)
     */
    public static boolean isValidMana(double value) {
        return value >= 0.0 && Double.isFinite(value);
    }

    /**
     * Checks if a mana value is valid (non-negative and finite).
     *
     * @param value the mana value to check
     * @return true if the value is valid (>= 0 and finite)
     */
    public static boolean isValidMana(float value) {
        return value >= 0.0f && Float.isFinite(value);
    }

    /**
     * Safely adds two mana values, clamping the result to non-negative.
     * If either value is invalid (negative or non-finite), returns 0.
     *
     * @param a the first mana value
     * @param b the second mana value
     * @return the sum clamped to non-negative, or 0 if either input is invalid
     */
    public static double safeAdd(double a, double b) {
        if (!isValidMana(a) || !isValidMana(b)) {
            return 0.0;
        }
        double result = a + b;
        // Check for overflow to positive infinity
        if (Double.isInfinite(result)) {
            return Double.MAX_VALUE;
        }
        return clampNonNegative(result);
    }

    /**
     * Safely subtracts two mana values, clamping the result to non-negative.
     * If either value is invalid (negative or non-finite), returns 0.
     *
     * @param a the first mana value
     * @param b the second mana value
     * @return the difference clamped to non-negative, or 0 if either input is invalid
     */
    public static double safeSubtract(double a, double b) {
        if (!isValidMana(a) || !isValidMana(b)) {
            return 0.0;
        }
        return clampNonNegative(a - b);
    }

    /**
     * Safely multiplies two mana values, clamping the result to non-negative.
     * If either value is invalid (negative or non-finite), returns 0.
     *
     * @param a the first mana value
     * @param b the second mana value
     * @return the product clamped to non-negative, or 0 if either input is invalid
     */
    public static double safeMultiply(double a, double b) {
        if (!isValidMana(a) || !isValidMana(b)) {
            return 0.0;
        }
        double result = a * b;
        // Check for overflow to positive infinity
        if (Double.isInfinite(result)) {
            return Double.MAX_VALUE;
        }
        return clampNonNegative(result);
    }

    /**
     * Safely divides two mana values, clamping the result to non-negative.
     * If either value is invalid (negative or non-finite), or divisor is zero, returns 0.
     *
     * @param a the dividend
     * @param b the divisor
     * @return the quotient clamped to non-negative, or 0 if invalid or division by zero
     */
    public static double safeDivide(double a, double b) {
        if (!isValidMana(a) || !isValidMana(b) || b == 0.0) {
            return 0.0;
        }
        return clampNonNegative(a / b);
    }

    /**
     * Linearly interpolates between two mana values.
     * If either value is invalid, returns the valid one or 0.
     *
     * @param a the first mana value
     * @param b the second mana value
     * @param t the interpolation factor (0.0 to 1.0)
     * @return the interpolated value clamped to non-negative
     */
    public static double lerp(double a, double b, double t) {
        if (!isValidMana(a) || !isValidMana(b)) {
            if (isValidMana(a)) return a;
            if (isValidMana(b)) return b;
            return 0.0;
        }
        // Clamp t to [0, 1] range
        t = Math.max(0.0, Math.min(1.0, t));
        return clampNonNegative(a + (b - a) * t);
    }

    /**
     * Gets the minimum of two mana values, ensuring non-negative result.
     *
     * @param a the first mana value
     * @param b the second mana value
     * @return the minimum of the two values, or 0 if either is invalid
     */
    public static double min(double a, double b) {
        if (!isValidMana(a) || !isValidMana(b)) {
            return 0.0;
        }
        return Math.min(a, b);
    }

    /**
     * Gets the maximum of two mana values, ensuring non-negative result.
     *
     * @param a the first mana value
     * @param b the second mana value
     * @return the maximum of the two values, or 0 if either is invalid
     */
    public static double max(double a, double b) {
        if (!isValidMana(a) || !isValidMana(b)) {
            return 0.0;
        }
        return Math.max(a, b);
    }

    /**
     * Checks if a value is approximately zero (within epsilon).
     *
     * @param value the value to check
     * @param epsilon the tolerance
     * @return true if the value is approximately zero
     */
    public static boolean isApproximatelyZero(double value, double epsilon) {
        return Math.abs(value) < epsilon;
    }

    /**
     * Checks if a value is approximately zero (within default epsilon).
     *
     * @param value the value to check
     * @return true if the value is approximately zero
     */
    public static boolean isApproximatelyZero(double value) {
        return isApproximatelyZero(value, 1e-10);
    }
}

package com.manacore.core.flow;

import com.manacore.core.storage.ChunkManaMap;

/**
 * Pure Java gradient calculator for mana flow direction and magnitude.
 * Computes the direction vector and magnitude between two mana positions.
 * Direction components are -1, 0, or 1 and point from higher mana to lower mana.
 * Magnitude is the absolute mana difference.
 */
public final class GradientCalculator {

    private GradientCalculator() {
        // Utility class - no instantiation
    }

    /**
     * Calculates the gradient between two positions in the mana map.
     *
     * @param map the mana storage map
     * @param ax the X coordinate of position A
     * @param ay the Y coordinate of position A
     * @param az the Z coordinate of position A
     * @param bx the X coordinate of position B
     * @param by the Y coordinate of position B
     * @param bz the Z coordinate of position B
     * @return a Gradient record with direction components and magnitude
     */
    public static Gradient calculate(ChunkManaMap map, int ax, int ay, int az, int bx, int by, int bz) {
        double manaA = map.get(ax, ay, az);
        double manaB = map.get(bx, by, bz);

        double difference = manaA - manaB;

        // Handle equal values - return zero gradient
        if (difference == 0.0) {
            return new Gradient(0, 0, 0, 0.0);
        }

        // Calculate direction components (-1, 0, or 1)
        // Direction points from higher mana to lower mana
        int dx = calculateDirectionComponent(ax, bx, difference);
        int dy = calculateDirectionComponent(ay, by, difference);
        int dz = calculateDirectionComponent(az, bz, difference);

        // Magnitude is absolute difference
        double magnitude = Math.abs(difference);

        return new Gradient(dx, dy, dz, magnitude);
    }

    /**
     * Calculates a single direction component based on coordinate difference and mana difference.
     * Returns -1, 0, or 1 pointing from higher mana to lower mana.
     */
    private static int calculateDirectionComponent(int coordA, int coordB, double manaDifference) {
        int coordDiff = coordB - coordA;

        if (coordDiff == 0) {
            return 0;
        }

        // If mana at A is higher than at B (positive difference), 
        // direction should point from A to B (which is the direction of coordDiff)
        // If mana at A is lower than at B (negative difference),
        // direction should point from B to A (which is opposite of coordDiff)
        if (manaDifference > 0) {
            // Higher at A, flow toward B
            return Integer.signum(coordDiff);
        } else {
            // Higher at B, flow toward A (opposite direction)
            return -Integer.signum(coordDiff);
        }
    }

    /**
     * Immutable record representing a mana gradient.
     * Direction components are -1, 0, or 1 and point from higher mana to lower mana.
     * Magnitude is the absolute mana difference (always non-negative).
     */
    public static record Gradient(int dx, int dy, int dz, double magnitude) {
        /**
         * Creates a new Gradient record.
         *
         * @param dx the X direction component (-1, 0, or 1)
         * @param dy the Y direction component (-1, 0, or 1)
         * @param dz the Z direction component (-1, 0, or 1)
         * @param magnitude the absolute mana difference (must be non-negative)
         */
        public Gradient {
            // Validate direction components
            if (dx != -1 && dx != 0 && dx != 1) {
                throw new IllegalArgumentException("dx must be -1, 0, or 1, got: " + dx);
            }
            if (dy != -1 && dy != 0 && dy != 1) {
                throw new IllegalArgumentException("dy must be -1, 0, or 1, got: " + dy);
            }
            if (dz != -1 && dz != 0 && dz != 1) {
                throw new IllegalArgumentException("dz must be -1, 0, or 1, got: " + dz);
            }
            if (magnitude < 0 || !Double.isFinite(magnitude)) {
                throw new IllegalArgumentException("magnitude must be non-negative and finite, got: " + magnitude);
            }
        }

        /**
         * Checks if this is a zero gradient (no direction, zero magnitude).
         *
         * @return true if all direction components are 0 and magnitude is 0
         */
        public boolean isZero() {
            return dx == 0 && dy == 0 && dz == 0 && magnitude == 0.0;
        }

        /**
         * Checks if the gradient has any direction component.
         *
         * @return true if any direction component is non-zero
         */
        public boolean hasDirection() {
            return dx != 0 || dy != 0 || dz != 0;
        }
    }
}
